class NanoTerminalState extends State<NanoTerminal> {
  TerminalDependencies get _deps =>
      widget.deps ?? TerminalDependencies.instance;
  IBinExecutor? get _shell => _deps.shell;
  RootfsManager? get _rootfs => _deps.rootfs;
  ProotManager? get _proot => _deps.proot;
  KaliManager? get _kali => _deps.kali;
  DockerManager? get _docker => _deps.docker;
  LinuxDistribution? get _ubuntu => _deps.ubuntu;

  /// TerminalServices para plugins (DIP). Cached to avoid re-allocation on
  /// every plugin call â€” the closures capture `this` so the instance stays
  /// valid for the widget's lifetime.
  late final TerminalServices _services = TerminalServices(
    ctx: _ctx,
    out: _out,
    after: _after,
    rootfsEnv: _deps.rootfsEnv,
    getEngine: () => _engine,
    audit: (cmd, tag, data) {},
    getShell: () => _shell,
    getRootfs: () => _rootfs,
    getDocker: () => _docker,
    getKali: () => _kali,
    getProot: () => _proot,
    getUbuntu: () => _ubuntu,
    openPty: (argv, {env, ldPreload}) =>
        _ptyOpen(argv, env: env, ldPreload: ldPreload),
    deviceId: _devId,
    onClear: () {
      if (mounted) _controller.clear();
    },
    onNavigate: (route) {
      if (!mounted) return;
      try {
        context.push(route);
      } catch (_) {
        Navigator.of(context).pushNamed(route);
      }
    },
    mounted: mounted,
  );

  final HardwareInfoService _hw = HardwareInfoService();
  Map<String, dynamic>? get _devId => _hw.deviceId;

  FocusNode get _fn => widget.focusNode ?? _localFn;
  TextEditingController get _in => widget.commandController ?? _localIn;
  late final FocusNode _localFn = FocusNode();
  late final TextEditingController _localIn = TextEditingController();
  final ScrollController _sc = ScrollController();
  final _controller = TerminalSessionController();
  List<TL> get _lines => _controller.lines;
  final _hist = <String>[], _timers = <Timer>[];
  final _ctx = TerminalCtx();
  // Ref: el CommandExecutor muta estos campos en la instancia de CmdExecCtx
  // que recibe por copia; el holder compartido conserva la mutación.
  final _hIdx = Ref<int>(-1);
  bool _ctrl = false, _alive = true;
  // TER-13: feedback de presión del FAB (escala al tocar).
  bool _fabPressed = false;
  // TER-14: FAB glass — colapsa a círculo compacto en reposo (estilo iOS
  // discreto) y se oculta mientras el panel Noar está abierto.
  bool _fabCollapsed = false;
  bool _fabHidden = false;
  Timer? _fabTimer;
  bool _initialCmdDone = false;
  LLMEngineClient? _engine;
  PtySession? _pty;
  final _ptyLines = <String>[]; // buffer acumulado del output PTY
  AnsiTerminal? _ansi;
  CronScheduler? _cron;
  final _cmds = <String, CmdFn>{};
  CommandDispatcher? _dispatcher;
  PtyManager? _ptyManager;

  String get _baseDir {
    final usr = _shell?.usrDir ?? _rootfs?.usrDir ?? '';
    return usr.endsWith('/usr') ? usr.substring(0, usr.length - 4) : usr;
  }

  String get _usrDir => _shell?.usrDir ?? _rootfs?.usrDir ?? '';

  bool _fabInit = false;
  // TER-12/14: FAB pill compacta (icono + "Noar") que colapsa a círculo.
  static const double _fabW = 104;
  static const double _fabH = 44;
  // TER-13: paleta pizarra/cian del FAB (sin verde neón en botones).
  static const Color _accent = Color(0xFF10B981);
  static const Color _fabText = Color(0xFFE2E8F0);

  final _bashCwd = Ref<String>('/');

  /// Fallback dart:io real (ver real_fs_shell.dart). Solo se usa en hosts sin
  /// binarios Android (desktop/tests): los comandos FS operan sobre el
  /// filesystem real del host bajo un raÃ­z sandbox. En Android manda el motor
  /// NanoRuntime (BusyBox vÃ­a Nanoshell FFI / rootfs).
  late final RealFsShell _realFs;

  /// Whitelist de comandos con ejecuciÃ³n real vÃ­a BusyBox (ver realCommands
  /// en terminal_types.dart). En hosts sin binarios Android, RealFsShell
  /// implementa el subconjunto dart:io como fallback real.
  String get _ps1 {
    final h = _devId?['hostname'] as String? ?? 'oppo';
    String home = _bashCwd.value;
    if (home == '/systemTemp/nano_real_root' || home == '/') {
      home = '~';
    } else if (home.startsWith('/systemTemp/nano_real_root/')) {
      home = home.substring('/systemTemp/nano_real_root'.length);
    }
    return 'nanoai@$h:$home\$ ';
  }

  bool _scrollPending = false;

  void _out(String t, Ln ty) {
    if (t.isEmpty && ty == Ln.stdout) return;
    if (!mounted) return;
    _controller.out(t, ty);
    if (!_scrollPending) {
      _scrollPending = true;
      WidgetsBinding.instance.addPostFrameCallback((_) {
        _scrollPending = false;
        if (_sc.hasClients) _sc.jumpTo(_sc.position.maxScrollExtent);
      });
    }
  }

  void _after(Duration d, VoidCallback cb) {
    late final Timer t;
    t = Timer(d, () {
      _timers.remove(t); // no acumular timers muertos en sesiones largas
      if (_alive) cb();
    });
    _timers.add(t);
  }

  @override
  void initState() {
    super.initState();
    _engine = widget.engine ?? LLMEngineClient();
    _ctx.cwd = widget.initialCwd;
    _realFs = RealFsShell(
      root: Platform.isAndroid
          ? '/data/data/dev.nanoai.mobile/files/nano'
          : '${Directory.systemTemp.path}/nano_real_root',
    );
    _buildRegistry(); // terminal-specific commands (ai, gpu, docker, kali, etc.)
    _fetchDeviceIdentity(); // async: uid, uname, hostname reales del device
    _initShell(); // async: extrae bash/toybox + verifica rootfs (crea ShellExecutor + RootfsManager compartidos)
    _noar.load(); // async: carga librerÃ­a de comandos guardados
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!_fabInit && mounted) {
        setState(() {
          _fabInit = true;
        });
        _restartFabTimer();
      }
    });
    _out('NanoTerminal  rootfs ARM64', Ln.header);
    _out('Modo: auto-PTY (bash interactivo real)', Ln.info);
    _out('', Ln.stdout);
    _loadHistory();
    HardwareKeyboard.instance.addHandler(_onKey);
  }

  void handleLifecycleState(AppLifecycleState state) {
    _ptyManager?.handleLifecycleState(state);
  }

  @override
  void didUpdateWidget(covariant NanoTerminal oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (widget.visible != oldWidget.visible) {
      final pm = _ptyManager;
      if (pm != null) {
        if (widget.visible) {
          pm.resumePolling();
        } else {
          pm.pausePolling();
        }
      }
      // TER-27: lazy open — el tab nace oculto en el IndexedStack y
      // visible NUNCA cambia desde false, así que el auto-open del init
      // gateado por visible deja el PTY sin abrir para siempre. Abrirlo
      // aquí, en la transición false→true, una sola vez.
      if (widget.visible &&
          !_autoPtyDone &&
          widget.initialCommand == null &&
          _shell?.initialized == true) {
        _autoOpenBash();
      }
    }
  }

  bool _autoPtyDone = false;

  /// TER-21/TER-27: auto bash PTY con PROMPT_COMMAND OSC 7 (cwd real).
  /// Un solo punto de apertura — init (si visible) y transición a visible.
  void _autoOpenBash() {
    _autoPtyDone = true;
    _after(
      const Duration(milliseconds: 500),
      () => _ptyOpen(
        ['bash'],
        env: {'PROMPT_COMMAND': r'printf "\033]7;file://%s\033\\" "$PWD"'},
      ),
    );
  }

  /// Obtiene identidad real del device (uid, uname, hostname, meminfo...) desde la plataforma. Los comandos usan estos datos para devolver info autÃ©ntica sin depender de execve() (bloqueado por SELinux en este device).
  Future<void> _fetchDeviceIdentity() => _hw.fetchDeviceIdentity();

  /// TER-21: OSC 7 del bash PTY — el shell reporta su cwd real con cada
  /// prompt. Sincroniza la línea de estado; antes era heurística Dart
  /// que se desfasaba al hacer `cd` dentro del bash real.
  void _onBashCwd(String cwd) {
    if (cwd == _bashCwd.value) {
      return;
    }
    debugPrint('[TER-21] bash cwd: $cwd');
    _bashCwd.value = cwd;
    if (mounted) setState(() {});
  }

  Future<double?> _readCpuTemp() => _hw.readCpuTemp();

  /// Extrae bash y toybox de assets/bin/ al dir privado de la app y los marca ejecutables. Luego verifica/instala el rootfs Termux completo.  Â¡IMPORTANTE! ShellExecutor y terminal_core comparten la MISMA instancia de RootfsManager para que el estado de instalaciÃ³n estÃ© sincronizado.
  Future<void> _initShell() async {
    try {
      if (_deps.rootfs == null) {
        await _deps.initAll(onProgress: (msg) => _out('[init] $msg', Ln.system));
      }
    } catch (e) {
      _out('[init] inicio parcial ($e)', Ln.warn);
    }

    // QUÉ: detiene la inicialización si la pestaña se cerró durante initAll.
    // POR QUÉ: evita crear managers o ejecutar el comando inicial tras dispose.
    if (!_alive || !mounted) return;
    _dispatcher = CommandDispatcher(
      shell: _shell,
      ctx: _ctx,
      out: _out,
      getBaseDir: () => _baseDir,
      getUsrDir: () => _usrDir,
      rootfsEnv: _deps.rootfsEnv,
    );
    _dispatcher!.buildRegistry();
    _ptyManager = PtyManager(
      rootfs: _rootfs,
      shell: _shell,
      rootfsEnv: _deps.rootfsEnv,
      onTitle: widget.onTitle,
      // TER-21: cwd real del bash (OSC 7) → línea de estado.
      onCwd: _onBashCwd,
      onSessionEnd: () {
        if (!mounted) return;
        setState(() {
          _ansi = null;
          _pty = null;
        });
      },
    );
    if (_shell?.initialized == true) {
      _out('[shell] bash + toybox listos en ${_shell!.binDir}', Ln.system);
    }
    final installed = _rootfs?.isInstalled == true;
    if (installed) {
      _out('[rootfs] detectado en ${_rootfs!.usrDir}', Ln.success);
      if (_shell != null && _shell!.usrDir != null && _shell!.baseDir != null) {
        final usr = _shell!.usrDir!;
        final base = _shell!.baseDir!;
        _ctx.env['HOME'] = '$base/home';
        _ctx.env['PREFIX'] = usr;
        _ctx.env['PATH'] = '$usr/bin:$usr/bin/applets:/system/bin:/system/xbin';
        _ctx.env['SHELL'] = '$usr/bin/bash';
        _ctx.env['TMPDIR'] = '$usr/tmp';
        _ctx.env['LD_LIBRARY_PATH'] = '$usr/lib';
        _ctx.env['TERMUX'] = 'true';
        _ctx.env['TERMUX_VERSION'] = '0.118.0';
        _ctx.env['TERMUX_APP__PID'] = '$pid';
        // TER-IDENT-01 — honestidad: este entorno no es F-Droid Termux,
        // es el bootstrap nanoMOBILE (pilar 4: jamás identidad falsa).
        _ctx.env['TERMUX_APK_RELEASE'] = 'nanoMOBILE';
        _ctx.env['TERMUX_APP__IS_DEBUGGABLE'] = 'false';
        _ctx.env['ANDROID_DATA'] = '/data';
        _ctx.env['ANDROID_ROOT'] = '/system';
        _ctx.env['LANG'] = 'en_US.UTF-8';
        _bashCwd.value = '$base/home';
        try {
          Directory('$base/home').createSync(recursive: true);
        } catch (_) {}
        try {
          Directory('$usr/tmp').createSync(recursive: true);
        } catch (_) {}
        try {
          Directory('$usr/var/lib/dpkg').createSync(recursive: true);
        } catch (_) {}
        try {
          Directory('$usr/var/log').createSync(recursive: true);
        } catch (_) {}
      }
    } else {
      _out('[rootfs] no instalado. Usa bootstrap si requieres apt/dpkg.', Ln.info);
    }
    // Auto-apertura PTY en la sesión activa: disponible con rootfs o con shell local
    if (widget.initialCommand == null && widget.visible) {
      _autoOpenBash();
    }
    if (_proot != null && _proot!.isReady) {
      _out('[proot] listo â†’ chroot sin root disponible', Ln.system);
    } else {
      _out('[proot] no disponible (ptrace bloqueado por SELinux?)', Ln.warn);
    }
    if (_kali != null) {
      await _kali!.checkInstalled();
      if (_kali!.isInstalled) {
        _out('[kali] detectado en ${_kali!.kaliRoot}', Ln.success);
      }
    }
    if (_docker != null) {
      _out('[docker] runtime listo', Ln.system);
    }

    // checkInstalled también es asíncrono; vuelve a comprobar el ciclo de vida.
    if (!_alive || !mounted) return;
    // Comando inicial inyectado desde la UI (card Kali del dashboard):
    // dispatcher ya construido, se ejecuta una sola vez.
    if (widget.initialCommand != null && !_initialCmdDone) {
      _initialCmdDone = true;
      CommandExecutor.execute(widget.initialCommand!, _execCtx());
    }
  }

  /// TER-14: programa el colapso del FAB a círculo compacto (estilo iOS:
  /// discreto en reposo). Se rearma en cada interacción.
  void _restartFabTimer() {
    _fabTimer?.cancel();
    _fabTimer = Timer(const Duration(milliseconds: 3500), () {
      if (mounted) setState(() => _fabCollapsed = true);
    });
  }

  /// TER-14: abre la Noar Library ocultando el FAB mientras el panel vive
  /// y rearmando el colapso al cerrar.
  void _fabTap() {
    final c = NanoThemeExtension.of(context).colors;
    final dark = Theme.of(context).brightness == Brightness.dark;
    final fg = dark ? const Color(0xFF21F2B2) : c.terminalGreen;
    _fabTimer?.cancel();
    setState(() => _fabHidden = true);
    showModalBottomSheet(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.transparent,
      builder: (_) =>
          NoarPanel(library: _noarLib, fg: fg, dark: dark, onUse: _useCommand),
    ).whenComplete(() {
      if (mounted) {
        setState(() => _fabHidden = false);
        _restartFabTimer();
      }
    });
  }

  @override
  void dispose() {
    _saveHistory();
    _alive = false;
    _fabTimer?.cancel();
    _ptyClose(notify: false);
    _ptyManager?.dispose();
    _ptyManager = null;
    for (final t in _timers) {
      t.cancel();
    }
    _timers.clear();
    _cron?.dispose();
    _cron = null;
    // TER-AUT-03: mata daemons activos (share_http / sshd_daemon) si el tab
    // se cierra sin `stop` explícito. El ShellExecutor pertenece a
    // TerminalDependencies (singleton); solo matamos los tags de ESTA sesión.
    _dispatcher?.dispose();
    _realFs.killActiveProcess();
    // El shell y el runtime Docker pertenecen a TerminalDependencies
    // (singleton compartido entre pestañas). Cerrar UNA pestaña no debe
    // matar los workers FFI ni el runtime de las demás sesiones: el dueño
    // único los libera en TerminalDependencies.dispose() (vida de la app).
    _localIn.dispose();
    _sc.dispose();
    _localFn.dispose();
    HardwareKeyboard.instance.removeHandler(_onKey);
    super.dispose();
  }

  /// Builds the legacy command registry. Common Linux commands (ls, cat, etc.) are handled by CommandDispatcher. This registry only adds terminal-specific commands (ai, gpu, docker, kali, help, noar, etc.) and simulated fallbacks.
  void _buildRegistry() {
    final s = _services;
    void r(String n, CmdFn f) => _cmds[n] = f;
    SystemPlugin().register(r, s);

    MonitorPlugin().register(r, s);
    ProcessPlugin().register(r, s);
    PkgPlugin().register(r, s);
    NetworkPlugin().register(r, s);
    DevOpsPlugin().register(r, s);
    DashboardPlugin().register(r, s);
    // crontab/watch REALES: timers que ejecutan CommandExecutor de verdad.
    // Registrados despuÃ©s de DevOpsPlugin para pisar cualquier stub.
    // P2: la instancia se guarda â€” antes su dispose() nunca se llamaba y
    // los timers de crontab/watch quedaban vivos para siempre.
    _cron = CronScheduler(
      execCmd: (raw) => CommandExecutor.execute(raw, _execCtx()),
      isAlive: () => _alive,
    )..register(r, _out);
    // pty REAL: abre sesión interactiva via _ptyOpen (el stub del plugin
    // nunca finge apertura — este registro lo reemplaza por el real).
    _cmds['pty'] = (a, c, o, af) {
      final cmd = a.isNotEmpty ? a[0] : 'bash';
      _ptyOpen([cmd, ...a.skip(1)], o: o);
    };
    _cmds['stat'] = (a, c, o, af) async {
      final all = a.contains('--all'),
          mem = all || a.contains('--memory'),
          cpu = all || a.contains('--cpu');
      o('â•â• NanoRuntime Status â•â•', Ln.header);
      if (mem) {
        final d = _devId;
        final double totalKb = (d?['memTotalKb'] as num?)?.toDouble() ?? 0.0;
        final double availKb = (d?['memAvailKb'] as num?)?.toDouble() ?? 0.0;
        final double usedKb = totalKb > 0 ? totalKb - availKb : 0.0;
        String fmt(double kb) => kb >= 1048576
            ? '${(kb / 1048576).toStringAsFixed(2)} GB'
            : '${(kb / 1024).toStringAsFixed(0)} MB';
        if (totalKb > 0) {
          final pct = totalKb > 0 ? (usedKb / totalKb * 100).round() : 0;
          final cachedKb = ProcFs.meminfo()['Cached'];
          final cacheStr = cachedKb != null
              ? ' | PageCache: ${fmt(cachedKb.toDouble())}'
              : '';
          o(
            'RAM: ${fmt(totalKb)} | Used: ${fmt(usedKb)} ($pct%) | Free: ${fmt(availKb)}$cacheStr',
            Ln.stdout,
          );
        } else {
          o('RAM: (leyendo /proc/meminfo...)', Ln.stdout);
        }
        o(
          'Modelo/KV: sin datos del motor LLM â€” usa "tune" para diagnÃ³stico real',
          Ln.info,
        );
      }
      if (cpu) {
        final cores =
            _devId?['cpuCores'] as int? ?? Platform.numberOfProcessors;
        final hw = _devId?['cpuHardware'] as String?;
        final tempC = await _readCpuTemp();
        final tempStr = tempC != null
            ? ' | Temp: ${tempC.toStringAsFixed(1)}Â°C'
            : '';
        o(
          'CPU: $cores cores${hw != null ? ' ($hw)' : ''}$tempStr | Procs: ${ProcFs.listPids().length}',
          Ln.stdout,
        );
      }
    };
    _cmds['infer'] = (a, c, o, af) {
      if (a.isEmpty) {
        o('infer: prompt requerido', Ln.stderr);
        return;
      }
      final prompt = a.join(' ');
      final engine = _engine;
      if (engine == null) {
        o('infer: motor LLM no disponible', Ln.stderr);
        return;
      }
      o('[NanoRuntime] Enviando a ${engine.baseUrl}...', Ln.system);
      final start = DateTime.now();
      engine
          .generate(prompt: prompt, maxTokens: 128)
          .then((res) {
            if (!_alive || !mounted) return;
            final ms = DateTime.now().difference(start).inMilliseconds;
            for (final line in res.text.split('\n')) {
              if (line.isNotEmpty) o(line, Ln.success);
            }
            o('${ms}ms @ ${res.tps?.toStringAsFixed(1) ?? "?"} tok/s', Ln.info);
          })
          .catchError((e) {
            if (!_alive || !mounted) return;
            o('infer: el motor no respondiÃ³ â€” $e', Ln.stderr);
          });
    };
    _cmds['ai'] = (a, c, o, af) {
      if (a.isEmpty) {
        o('ai: escribe un prompt. Ej: ai Â¿cÃ³mo optimizar RAM?', Ln.stderr);
        return;
      }
      final prompt = a.join(' ');
      final engine = _engine;
      if (engine == null) {
        o('ai: motor LLM no disponible', Ln.stderr);
        return;
      }
      o('[NanoAI] Pensando... (${engine.baseUrl})', Ln.info);
      engine
          .generate(prompt: prompt, maxTokens: 512)
          .then((res) {
            if (!_alive || !mounted) return;
            for (final line in res.text.split('\n')) {
              if (line.isNotEmpty) o(line, Ln.stdout);
            }
            if (res.tps != null) {
              o('${res.tps!.toStringAsFixed(1)} tok/s', Ln.info);
            }
          })
          .catchError((e) {
            if (!_alive || !mounted) return;
            o(
              'ai: el motor no respondiÃ³. Â¿EstÃ¡ corriendo llama.cpp en 127.0.0.1:8080?',
              Ln.stderr,
            );
            o('  $e', Ln.stderr);
          });
    };
    _cmds['tune'] = (a, c, o, af) async {
      o('â•â• NanoAI Auto-Tune â•â•', Ln.header);
      final mem = ProcFs.meminfo();
      final totalMb = (mem['MemTotal'] ?? 0) ~/ 1024;
      final availMb = (mem['MemAvailable'] ?? mem['MemFree'] ?? 0) ~/ 1024;
      final cores = _devId?['cpuCores'] as int? ?? Platform.numberOfProcessors;
      final tempC = await _readCpuTemp();
      o(
        'Device: ${totalMb}MB RAM, ${availMb}MB libre, $cores cores'
        '${tempC != null ? ', ${tempC.toStringAsFixed(1)}Â°C' : ''}',
        Ln.info,
      );
      final engine = _engine;
      if (engine == null) {
        o('Motor LLM: no configurado (sin engine client)', Ln.warn);
        o('Sugerencias: instala llama.cpp en 127.0.0.1:8080', Ln.info);
        return;
      }
      o('Motor URL: ${engine.baseUrl}', Ln.info);
      final online = await engine.isOnline();
      if (!online) {
        o('Motor: OFFLINE (no responde en ${engine.baseUrl})', Ln.warn);
        o('Sugerencia: lanza llama.cpp con --server --port 8080', Ln.info);
        return;
      }
      o('Motor: ONLINE', Ln.success);
      o('Benchmark TPS... (prompt de prueba)', Ln.info);
      try {
        final res = await engine.generate(
          prompt: 'Hello',
          maxTokens: 10,
          temperature: 0.0,
        );
        o(
          'Respuesta: "${res.text.length > 40 ? '${res.text.substring(0, 40)}...' : res.text}"',
          Ln.stdout,
        );
        if (res.tps != null) {
          o('Velocidad: ${res.tps!.toStringAsFixed(1)} tok/s', Ln.success);
