void _out(String t, Ln ty) {
    if (t.isEmpty && ty == Ln.stdout) return;
    if (!mounted) return;
    _controller.out(t, ty);
    if (!_scrollPending) {
      _scrollPending = true;
      WidgetsBinding.instance.addPostFrameCallback((_) {
        _scrollPending = false;
        if (_sc.hasClients) _sc.jumpTo(_sc.position.maxScrollExtent);
      });
    }
