        ? 'bash + toybox (modo comando)'
        : 'Terminal local (modo comando)';
    final headerColor = _ptyActive
        ? c.success
        : fg.withValues(alpha: 0.6);
    return Column(
      children: [
        // TER-15: header glass — gradiente pizarra + dot de estado con
        // glow del color del estado + texto con letterSpacing.
        Container(
          width: double.infinity,
          padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 6),
          decoration: BoxDecoration(
            gradient: LinearGradient(
              begin: Alignment.topLeft,
              end: Alignment.bottomRight,
              colors: dark
                  ? [const Color(0xFF0E2238), const Color(0xFF07192B)]
                  : [c.terminalBg.withValues(alpha: 0.9), c.terminalBg],
            ),
            border: Border(
              bottom: BorderSide(color: fg.withValues(alpha: 0.08)),
            ),
          ),
          child: Row(
            children: [
              Container(
                width: 6,
                height: 6,
                decoration: BoxDecoration(
                  color: headerColor,
                  shape: BoxShape.circle,
                  boxShadow: [
                    BoxShadow(
                      color: headerColor.withValues(alpha: 0.5),
                      blurRadius: 6,
                      spreadRadius: 1,
                    ),
                  ],
                ),
              ),
              const SizedBox(width: 7),
              Text(
                headerLabel,
                style: TextStyle(
                  fontFamily: 'JetBrainsMono',
                  fontSize: 10,
                  letterSpacing: 0.5,
                  fontWeight: FontWeight.w600,
                  color: headerColor,
                ),
              ),
              const Spacer(),
              Text(
                'NANORUNTIME',
                style: TextStyle(
                  fontFamily: 'JetBrainsMono',
                  fontSize: 9,
                  letterSpacing: 1.2,
                  fontWeight: FontWeight.w700,
                  color: fg.withValues(alpha: 0.3),
                ),
              ),
            ],
          ),
        ),
        Expanded(
          child: Stack(
            children: [
              Positioned.fill(
                child: IgnorePointer(
                  child: CustomPaint(
                    painter: _ScanlinePainter(
                      _ansi != null ? fg.withValues(alpha: 0.4) : fg,
                    ),
                  ),
                ),
              ),
              if (_ansi != null)
                GestureDetector(
                  onTap: () => _fn.requestFocus(),
                  onTapDown: _ansi?.mouseEnabled == true
                      ? (d) {
                          final m = AnsiMetrics.measure();
                          final row = (d.localPosition.dy / m.cellH).floor();
                          final col = (d.localPosition.dx / m.cellW).floor();
                          _pty?.writeBytes([
                            0x1b,
                            0x5b,
                            0x4d,
                            32,
                            col + 33,
                            row + 33,
                          ]);
                        }
                      : null,
                  child: ColoredBox(
                    color: Theme.of(context).scaffoldBackgroundColor,
                    child: LayoutBuilder(
                      builder: (context, cons) {
                        _applyPtySize(cons.maxWidth, cons.maxHeight);
                        return SelectionArea(child: AnsiTerminalView(_ansi!));
                      },
                    ),
                  ),
                )
              else
                SelectionArea(
                  child: GestureDetector(
                    behavior: HitTestBehavior.opaque,
                    onTap: () => _fn.requestFocus(),
                    child: ListenableBuilder(
                      listenable: _controller,
                      builder: (context, _) {
                        return ListView.builder(
                          controller: _sc,
                          physics: const BouncingScrollPhysics(),
                          padding: const EdgeInsets.symmetric(
                            horizontal: 16,
                            vertical: 12,
                          ),
                          itemCount: _lines.length,
                          itemBuilder: (_, i) {
                            final line = _lines[i];
                            return Padding(
                              padding: const EdgeInsets.only(bottom: 1.5),
                              child: Row(
                                crossAxisAlignment: CrossAxisAlignment.start,
                                children: [
                                  SizedBox(
                                    width: 32,
                                    child: Text(
                                      '${i + 1}',
                                      style: TextStyle(
                                        fontFamily: 'JetBrainsMono',
                                        fontSize: 10,
                                        color: fg.withValues(alpha: 0.15),
                                        height: 1.6,
                                      ),
                                    ),
                                  ),
                                  Expanded(
                                    child: Text(
                                      line.text,
                                      style: TextStyle(
                                        fontFamily: 'JetBrainsMono',
                                        fontSize: 12.5,
                                        color: _c(line.type, fg, c),
                                        height: 1.6,
                                      ),
                                    ),
                                  ),
                                ],
                              ),
                            );
                          },
                        );
                      },
                    ),
                  ),
                ),
              _buildFab(c, chrome, dark),
            ],
          ),
        ),
        if (_ptyActive)
          TerminalModifierBar(
            fg: fg,
            chrome: chrome,
            ctrlActive: _ctrl,
            onToggleCtrl: () {
              setState(() {
                _ctrl = !_ctrl;
              });
            },
            onWriteBytes: (bytes) => _pty?.writeBytes(bytes),
            onWrite: (text) => _pty?.write(text),
            bracketedPasteEnabled: _ansi?.screen.bracketedPasteMode ?? false,
          ),
      ],
    );
  }

