class _SuggestionChipState extends State<_SuggestionChip> {
  bool _pressed = false;

  @override
  Widget build(BuildContext context) {
    return GestureDetector(
      onTapDown: (_) => setState(() => _pressed = true),
      onTapUp: (_) => setState(() => _pressed = false),
      onTapCancel: () => setState(() => _pressed = false),
      onTap: widget.onTap,
      child: AnimatedScale(
        scale: _pressed ? 0.92 : 1.0,
        duration: const Duration(milliseconds: 90),
        curve: Curves.easeOut,
        child: AnimatedContainer(
          duration: const Duration(milliseconds: 140),
          curve: Curves.easeOutCubic,
          padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 5),
          decoration: BoxDecoration(
            color: _pressed
                ? widget.fg.withValues(alpha: 0.16)
                : widget.fg.withValues(alpha: 0.05),
            borderRadius: BorderRadius.circular(7),
            border: Border.all(
              color: _pressed
                  ? widget.fg.withValues(alpha: 0.35)
                  : widget.fg.withValues(alpha: 0.08),
            ),
            boxShadow: _pressed
                ? [
                    BoxShadow(
                      color: widget.fg.withValues(alpha: 0.15),
                      blurRadius: 8,
                    ),
                  ]
                : null,
          ),
          child: Text(
            widget.label,
            style: TextStyle(
              fontFamily: 'JetBrainsMono',
              fontSize: 11.5,
              fontWeight: _pressed ? FontWeight.w700 : FontWeight.w500,
              color: _pressed ? widget.fg : widget.fg.withValues(alpha: 0.7),
            ),
          ),
        ),
      ),
    );
  }
}

/// Subtle scanline effect for retro terminal feel
class _ScanlinePainter extends CustomPainter {
  final Color color;
  _ScanlinePainter(this.color);
  @override
  void paint(Canvas canvas, Size size) {
    final paint = Paint()..color = color.withValues(alpha: 0.015);
    for (double y = 0; y < size.height; y += 3) {
      canvas.drawLine(Offset(0, y), Offset(size.width, y), paint);
    }
  }

  @override
  bool shouldRepaint(covariant CustomPainter old) => false;
}

